// Program 10.4: Area and perimeter of a rectangular classroom
#include <iostream>
using namespace std;

int main() {
    double length, width;
    cout << "Enter length (m): ";
    cin >> length;
    cout << "Enter width (m): ";
    cin >> width;

    double area = length * width;
    double perimeter = 2 * (length + width);

    cout << "Area      = " << area << " sq m" << endl;
    cout << "Perimeter = " << perimeter << " m" << endl;
    return 0;
}

// Program 10.5: Simple interest on a bank deposit
#include <iostream>
using namespace std;

int main() {
    double principal, rate, years;
    cout << "Principal (Rs): ";
    cin >> principal;
    cout << "Rate (% per year): ";
    cin >> rate;
    cout << "Time (years): ";
    cin >> years;

    double si = principal * rate * years / 100;
    double amount = principal + si;

    cout << "Simple interest = Rs " << si << endl;
    cout << "Total amount    = Rs " << amount << endl;
    return 0;
}

// Program 10.6: Celsius to Fahrenheit
#include <iostream>
using namespace std;

int main() {
    double c;
    cout << "Temperature in Celsius: ";
    cin >> c;
    double f = c * 9 / 5 + 32;
    cout << c << " C = " << f << " F" << endl;
    return 0;
}

// Program 10.7: Arithmetic operators in action
#include <iostream>
using namespace std;

int main() {
    int a = 17, b = 5;
    cout << "a + b = " << a + b << endl;
    cout << "a - b = " << a - b << endl;
    cout << "a * b = " << a * b << endl;
    cout << "a / b = " << a / b << endl;    // integer division
    cout << "a % b = " << a % b << endl;    // remainder
    cout << "17.0 / 5 = " << 17.0 / 5 << endl;
    cout << "(double)a / b = " << (double)a / b << endl;
    return 0;
}

// Program 10.8: Increment, relational and logical operators
#include <iostream>
using namespace std;

int main() {
    int x = 5;
    int y = x++;      // y gets 5, then x becomes 6
    cout << "After y = x++ : y = " << y << ", x = " << x << endl;
    int z = ++x;      // x becomes 7, then z gets 7
    cout << "After z = ++x : z = " << z << ", x = " << x << endl;

    int age = 15, marks = 82;
    cout << boolalpha;
    cout << "age >= 18              : " << (age >= 18) << endl;
    cout << "marks > 80             : " << (marks > 80) << endl;
    cout << "age < 18 && marks > 80 : " << (age < 18 && marks > 80) << endl;
    cout << "age >= 18 || marks > 80: " << (age >= 18 || marks > 80) << endl;
    cout << "!(marks > 80)          : " << !(marks > 80) << endl;
    return 0;
}

// Program 10.9: Shop bill with 18% GST
#include <iostream>
#include <string>
using namespace std;

int main() {
    string item;
    double price;
    int qty;
    const double GST_RATE = 18.0;

    cout << "Item name: ";
    getline(cin, item);
    cout << "Price of one item (Rs): ";
    cin >> price;
    cout << "Quantity: ";
    cin >> qty;

    double amount = price * qty;
    double gst = amount * GST_RATE / 100;
    double total = amount + gst;

    cout << "\n----- BILL -----\n";
    cout << "Item     : " << item << endl;
    cout << "Amount   : Rs " << amount << endl;
    cout << "GST 18%  : Rs " << gst << endl;
    cout << "Total    : Rs " << total << endl;
    return 0;
}
